let links = $('a[href^="#"]:not(.has-dropdown)');
let siteHeader = $('.c-site-header');
let urlPage = window.location.href;
let idLink = $('#'+urlPage.split('#')[1]);


if (links.length) {
    $('body').on('click', 'a[href^="#"]:not(.has-dropdown)', function () {
        let targetLink = $(this).attr('href');
        console.log('links');

        $('html, body').animate({
            scrollTop: $(targetLink).offset().top
        });
    });
}

if (idLink.length) {
    $(window).on('load', function () {
        $('html, body').animate({
            scrollTop: idLink.offset().top
        });
    });
}